<?php declare(strict_types=1);
require_once __DIR__.'/../../../src/Finance/Tax/TaxReviewQueue.php';
$reviewYearRaw=input($_GET,'year',date('Y'));
if(!preg_match('/^[0-9]{4}$/D',$reviewYearRaw))throw new DomainException('Bitte ein gültiges Jahr auswählen.');
$review=(new \Kulturhus\Verein\TaxReviewQueue($db,(string)$_SESSION['actor']))->build((int)$reviewYearRaw);
$reviewSearch=mb_substr(input($_GET,'q'),0,200);
$reviewMatches=static fn($row)=>$reviewSearch===''||mb_stripos(implode(' ',[$row['number'],$row['title'],$row['counterparty'],$row['date'],...array_column($row['reasons'],'message')]),$reviewSearch)!==false;
$reviewRows=array_values(array_filter($review['rows'],$reviewMatches));
$reviewUndated=array_values(array_filter($review['undated_rows'],$reviewMatches));
?>
<link rel="stylesheet" href="tax-review-queue.css?v=1">
<div class="page-heading"><h1>Kassenprüfung – Nacharbeiten</h1></div>
<div class="content tax-review-queue">
<section class="card"><h2>Was muss noch geklärt werden?</h2><p>Hier stehen noch nicht erfasste Eingangsrechnungen und fehlende Zuordnungen aus den gespeicherten Belegen und Kontoumsätzen. Öffnen Sie einen Vorgang, korrigieren Sie die Angaben und kehren Sie zur Liste zurück. Erledigte Punkte verschwinden nach dem erneuten Anzeigen automatisch.</p>
<p>Auch noch nicht bezahlte Rechnungen werden geprüft. Eine leere Liste bestätigt noch keine vollständige oder korrekte Steuererklärung.</p>
<details><summary>Welche Daten werden geprüft?</summary><p>Belege werden nach ihrem Belegdatum berücksichtigt, Zahlungen nach ihrem Zahlungsdatum. Bei offenen Eingangsrechnungen wird das Rechnungsdatum aus einer aktuellen Erkennung verwendet. Ohne eindeutiges Rechnungsjahr erscheint die Datei gesondert unter „Rechnungsjahr noch prüfen“.</p><p>Die Beträge dieser Liste dürfen nicht zu einem Jahresergebnis addiert werden. Erkennungsvorschläge sind noch keine Buchung oder Zahlung.</p><p>Die Liste ist eine Arbeitshilfe für Kassenwart und Kassenprüfung. Nicht importierte Unterlagen kann sie nicht erkennen. Ein leerer BU-Schlüssel wird nicht pauschal als Fehler behandelt.</p></details>
<?php if(!$review['can_write']): ?><p>Sie können die Angaben ansehen. Bitte den Kassenwart um die erforderlichen Korrekturen bitten.</p><?php endif ?>
<form method="get" class="tax-review-filters"><?= hidden('view','finance').hidden('tab','tax').hidden('tax_review','1') ?><label>Jahr<select class="form-control" name="year"><?php for($yr=(int)date('Y');$yr>=2000;--$yr): ?><option value="<?= $yr ?>" <?= $yr===$review['year']?'selected':'' ?>><?= $yr ?></option><?php endfor ?></select></label><label>Vorgang oder Hinweis suchen<input class="form-control" name="q" maxlength="200" value="<?= e($reviewSearch) ?>" type="search"></label><button class="btn btn-solid theme-primary">Liste anzeigen</button></form>
<p><strong><?= count($reviewRows) ?> von <?= $review['count'] ?> Vorgängen</strong> mit Nacharbeiten im Jahr <?= $review['year'] ?>.</p><?php if($review['undated_count']): ?><p>Zusätzlich: <a href="#tax-inbox-undated"><?= $review['undated_count'] ?> Eingangsrechnungen mit ungeklärtem Jahr prüfen</a>.</p><?php endif ?><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['view'=>'finance','tab'=>'tax','year'=>$review['year']])) ?>">Zur Steuervorbereitung</a></section>
<?php if(!$reviewRows): ?><section class="card"><h2><?= $reviewSearch!==''?'Keine Treffer im gewählten Jahr':'Keine zugeordneten Nacharbeiten im gewählten Jahr' ?></h2><p><?= $reviewSearch!==''?'Prüfen Sie auch die Rechnungen mit ungeklärtem Jahr oder entfernen Sie den Suchtext.':($review['undated_count']?'Bitte die Eingangsrechnungen mit ungeklärtem Jahr unten prüfen.':'Bitte zusätzlich nicht importierte Unterlagen und die Jahresangaben in der Steuervorbereitung prüfen.') ?></p></section><?php endif ?>
<?php $renderReviewRow=static function(array $row,bool $canWrite):void { ?><article class="card"><h2><?= e($row['title']) ?></h2><p><strong><?= e($row['number']) ?></strong> · <?= ($row['date_basis']??'')==='document_fallback'?'Dokumentdatum ':'' ?><?= e($row['date']) ?> · <?= $row['cents']===null?'Betrag noch prüfen':e(\Kulturhus\Verein\Finance::decimal($row['cents'])).' EUR' ?></p><?php if($row['counterparty']!==''): ?><p><?= e($row['counterparty']) ?></p><?php endif ?><?php foreach($row['basis'] as $basis): ?><p class="muted"><?= e($basis) ?></p><?php endforeach ?><ul><?php foreach($row['reasons'] as $reason): ?><li><?= e($reason['message']) ?></li><?php endforeach ?></ul><a class="btn btn-solid theme-primary button" href="<?= e($row['url']) ?>"><?= $canWrite?(str_starts_with($row['id'],'inbox:')?'Rechnung prüfen und erfassen':'Vorgang öffnen und korrigieren'):'Vorgang ansehen' ?></a></article><?php };
foreach($reviewRows as $row)$renderReviewRow($row,$review['can_write']); ?>
<?php if($review['undated_count']): ?><section class="card" id="tax-inbox-undated"><h2>Rechnungsjahr noch prüfen</h2><p><strong><?= count($reviewUndated) ?> von <?= $review['undated_count'] ?> offenen Eingangsrechnungen</strong> haben noch kein verlässlich erkanntes Rechnungsjahr. Sie sind keinem Steuerjahr zugeordnet und werden deshalb bei jeder Jahresauswahl hier angezeigt.</p></section><?php foreach($reviewUndated as $row)$renderReviewRow($row,$review['can_write']);endif ?>
</div>
